import { useState } from 'react'
import { Navigate } from 'react-router-dom'
import { Building2, Camera, Check, Plus, Save, Trash2 } from 'lucide-react'
import { AppLayout } from '@/components/layout'
import Button from '@/components/ui/Button'
import Input from '@/components/ui/Input'
import TimeInput from '@/components/ui/TimeInput'
import DateInput from '@/components/ui/DateInput'
import { Skeleton } from '@/components/ui/Skeleton'
import { supabase } from '@/lib/supabase'
import { toast } from '@/lib/toast'
import { confirm } from '@/lib/confirm'
import TherapistsSection from '@/components/admin/TherapistsSection'
import AccountPlanCard from '@/components/settings/AccountPlanCard'
import { useAuthContext } from '@/hooks/AuthProvider'
import { useTenant } from '@/hooks/useTenant'
import {
  useAccountBlocks,
  useCreateAccountBlock,
  useDeleteAvailabilityBlock,
} from '@/hooks/useBooking'
import '../Settings.css'

export default function AccountScreen() {
  const { user } = useAuthContext()
  const { tenant, loading: loadingTenant } = useTenant()
  const isOwner = user?.role === 'owner'

  const [name, setName] = useState(tenant?.name || '')
  const [phone, setPhone] = useState((tenant?.settings?.phone as string) || '')
  const [address, setAddress] = useState((tenant?.settings?.address as string) || '')
  const [saving, setSaving] = useState(false)

  // "Conta" é exclusiva do owner.
  if (!isOwner) {
    return <Navigate to="/settings/perfil" replace />
  }

  const handleSave = async () => {
    if (!tenant) return

    setSaving(true)
    try {
      const { error } = await supabase
        .from('tenants')
        .update({
          name,
          settings: {
            ...(tenant.settings || {}),
            phone,
            address,
          },
        })
        .eq('id', tenant.id)

      if (error) throw error
      toast('Configurações salvas!')
    } catch {
      toast('Erro ao salvar configurações', 'error')
    } finally {
      setSaving(false)
    }
  }

  if (loadingTenant) {
    return (
      <AppLayout title="Conta">
        <div className="settings-page">
          <Skeleton height="400px" />
        </div>
      </AppLayout>
    )
  }

  return (
    <AppLayout title="Conta" subtitle="Dados do consultório e equipe">
      <div className="settings-page">
        <div className="settings-section">
          {/* Logo */}
          <div className="settings-card">
            <h3>Logo da Conta</h3>
            <div className="avatar-section">
              <div className="avatar-preview avatar-preview--square">
                {tenant?.logo_url ? <img src={tenant.logo_url} alt="" /> : <Building2 size={48} />}
              </div>
              <div className="avatar-actions">
                <Button variant="secondary" size="sm" disabled>
                  <Camera size={16} />
                  Alterar logo
                </Button>
                <p className="avatar-hint">Em breve: upload de logo</p>
              </div>
            </div>
          </div>

          {/* Clinic Info */}
          <div className="settings-card">
            <h3>Informações da Conta</h3>
            <div className="settings-form">
              <Input
                label="Nome da conta"
                value={name}
                onChange={e => setName(e.target.value)}
                placeholder="Nome que aparece no sistema"
              />
              <Input
                label="Telefone/WhatsApp"
                value={phone}
                onChange={e => setPhone(e.target.value)}
                placeholder="(00) 00000-0000"
              />
              <Input
                label="Endereço"
                value={address}
                onChange={e => setAddress(e.target.value)}
                placeholder="Rua, número, bairro, cidade"
              />
              <div className="settings-form-actions">
                <Button onClick={handleSave} disabled={saving}>
                  <Save size={18} />
                  {saving ? 'Salvando...' : 'Salvar alterações'}
                </Button>
              </div>
            </div>
          </div>

          {/* Plano da conta (owner-only, herdado do gate da aba Conta) */}
          <AccountPlanCard />

          {/* Terapeutas (owner-only, herdado do gate da aba Conta) */}
          <TherapistsSection />

          {/* Bloqueios da conta inteira (feriados, recesso) — owner-only */}
          <AccountBlocksSettings />
        </div>
      </div>
    </AppLayout>
  )
}

// ============================================================
// Account Blocks Settings (bloqueios da conta inteira — owner)
// ============================================================

function AccountBlocksSettings() {
  const { data: blocks, isLoading } = useAccountBlocks()
  const createBlock = useCreateAccountBlock()
  const deleteBlock = useDeleteAvailabilityBlock()

  const [date, setDate] = useState('')
  const [allDay, setAllDay] = useState(true)
  const [start, setStart] = useState('09:00')
  const [end, setEnd] = useState('12:00')
  const [reason, setReason] = useState('')

  const handleAdd = async () => {
    if (!date) {
      toast('Selecione uma data', 'error')
      return
    }
    if (!allDay && start >= end) {
      toast('O horário final deve ser maior que o inicial', 'error')
      return
    }
    await createBlock.mutateAsync({
      date,
      start_time: allDay ? null : start + ':00',
      end_time: allDay ? null : end + ':00',
      reason: reason.trim() || null,
    })
    setReason('')
  }

  const handleDelete = async (id: string) => {
    const confirmed = await confirm({
      message: 'Remover este bloqueio da conta?',
      confirmLabel: 'Remover',
      variant: 'danger',
    })
    if (confirmed) deleteBlock.mutate(id)
  }

  const fmtDate = (d: string) => {
    try {
      return new Date(d + 'T12:00:00').toLocaleDateString('pt-BR')
    } catch {
      return d
    }
  }

  return (
    <div className="settings-card">
      <h3>Bloqueios da Conta</h3>
      <p className="settings-description">
        Bloqueie datas para <strong>toda a conta</strong> (feriados, recesso, fechamento). Afeta a
        agenda de <strong>todos os terapeutas</strong> ao mesmo tempo. Para bloquear só a sua
        agenda, use a aba Agendamento.
      </p>

      <div className="settings-form">
        <div className="settings-form-row">
          <div className="form-group">
            <label className="form-label">Data</label>
            <DateInput value={date} onChange={setDate} />
          </div>
          <div className="form-group">
            <label className="form-label">Tipo</label>
            <div className="days-selector">
              <button
                type="button"
                className={`day-chip ${allDay ? 'day-chip--selected' : ''}`}
                onClick={() => setAllDay(true)}
              >
                {allDay && <Check size={14} />}
                Dia inteiro
              </button>
              <button
                type="button"
                className={`day-chip ${!allDay ? 'day-chip--selected' : ''}`}
                onClick={() => setAllDay(false)}
              >
                {!allDay && <Check size={14} />}
                Faixa de horário
              </button>
            </div>
          </div>
        </div>

        {!allDay && (
          <div className="availability-times">
            <TimeInput label="Início" value={start} onChange={setStart} />
            <TimeInput label="Fim" value={end} onChange={setEnd} />
          </div>
        )}

        <Input
          label="Motivo (opcional)"
          value={reason}
          onChange={e => setReason(e.target.value)}
          placeholder="Ex.: Feriado nacional, recesso"
        />

        <div className="settings-form-actions">
          <Button onClick={handleAdd} disabled={createBlock.isPending || !date}>
            <Plus size={18} />
            Adicionar bloqueio da conta
          </Button>
        </div>
      </div>

      {isLoading ? (
        <Skeleton height="80px" />
      ) : !blocks?.length ? (
        <p className="settings-empty">Nenhum bloqueio da conta cadastrado</p>
      ) : (
        <div className="blocks-list">
          {blocks.map(b => (
            <div key={b.id} className="block-item">
              <div className="block-item-info">
                <span className="block-item-date">{fmtDate(b.date)}</span>
                <span className="block-item-time">
                  {b.start_time && b.end_time
                    ? `${b.start_time.slice(0, 5)} – ${b.end_time.slice(0, 5)}`
                    : 'Dia inteiro'}
                </span>
                {b.reason && <span className="block-item-reason">{b.reason}</span>}
              </div>
              <button
                className="availability-slot-remove"
                onClick={() => handleDelete(b.id)}
                title="Remover"
              >
                <Trash2 size={14} />
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  )
}
