import { useState } from 'react'
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import { ArrowDownCircle, ArrowRightCircle, ArrowUpCircle, CreditCard, Send } from 'lucide-react'
import { useTenant } from '@/hooks/useTenant'
import {
  fetchTenantBillingSummary,
  listPlanChangeRequests,
  listPlans,
  requestPlanChange,
} from '@/services/platform'
import type { BillingPlan } from '@/types/database'
import { toast } from '@/lib/toast'
import Button from '@/components/ui/Button'
import { Skeleton } from '@/components/ui/Skeleton'
import './AccountPlanCard.css'

function fmtPrice(cents: number, currency = 'BRL', interval = 'month'): string {
  if (cents === 0) return 'Grátis'
  const v = (cents / 100).toLocaleString('pt-BR', { style: 'currency', currency })
  return `${v}/${interval === 'year' ? 'ano' : 'mês'}`
}
function fmtLimit(v: number | null | undefined): string {
  return v === null || v === undefined ? 'Ilimitado' : String(v)
}

function UsageBar({
  label,
  used,
  max,
}: {
  label: string
  used: number
  max: number | null | undefined
}) {
  const unlimited = max === null || max === undefined
  const pct = unlimited ? 0 : Math.min(100, Math.round((used / Math.max(max, 1)) * 100))
  const level = unlimited ? 'ok' : pct >= 100 ? 'full' : pct >= 80 ? 'warn' : 'ok'
  return (
    <div className="apc-usage">
      <div className="apc-usage-head">
        <span>{label}</span>
        <span className="apc-usage-count">
          {used} / {unlimited ? '∞' : max}
        </span>
      </div>
      <div className="apc-usage-track">
        <div className={`apc-usage-fill apc-usage-fill--${level}`} style={{ width: `${pct}%` }} />
      </div>
    </div>
  )
}

export default function AccountPlanCard() {
  const { tenant } = useTenant()
  const queryClient = useQueryClient()
  const tenantId = tenant?.id ?? ''

  const [requestPlanId, setRequestPlanId] = useState('')
  const [message, setMessage] = useState('')

  const { data: summary, isLoading } = useQuery({
    queryKey: ['platform', 'billing-summary', tenantId],
    queryFn: () => fetchTenantBillingSummary(tenantId),
    enabled: !!tenantId,
  })
  const { data: plans } = useQuery({ queryKey: ['platform', 'plans'], queryFn: listPlans })
  const { data: pending } = useQuery({
    queryKey: ['platform', 'my-plan-request', tenantId],
    queryFn: () => listPlanChangeRequests(true),
    enabled: !!tenantId,
  })

  const myPending = (pending ?? []).find(r => r.tenant_id === tenantId && r.status === 'pending')

  // Plano atual e selecionado (da lista de planos), para comparar preço/limites.
  const currentPlan: BillingPlan | undefined = (plans ?? []).find(
    p => p.slug === summary?.plan_slug
  )
  const selectedPlan: BillingPlan | undefined = (plans ?? []).find(p => p.id === requestPlanId)

  // upgrade | downgrade | lateral, pela comparação de preço.
  const changeKind: 'upgrade' | 'downgrade' | 'lateral' | null = (() => {
    if (!selectedPlan || !currentPlan) return null
    if (selectedPlan.price_cents > currentPlan.price_cents) return 'upgrade'
    if (selectedPlan.price_cents < currentPlan.price_cents) return 'downgrade'
    return 'lateral'
  })()

  const mutation = useMutation({
    mutationFn: () => requestPlanChange(requestPlanId, message.trim() || null),
    onSuccess: res => {
      if (res.error) {
        toast(
          res.error.includes('only the account owner')
            ? 'Apenas o dono da conta pode solicitar.'
            : res.error,
          'error'
        )
        return
      }
      toast('Solicitação enviada. Nossa equipe vai avaliar.')
      setMessage('')
      setRequestPlanId('')
      void queryClient.invalidateQueries({ queryKey: ['platform', 'my-plan-request', tenantId] })
    },
  })

  if (isLoading) return <Skeleton width="100%" height="220px" />
  if (!summary) return null

  const rebaixado = summary.effective_freemium && summary.subscription_status !== 'active'
  const emTeste = summary.subscription_status === 'trialing'
  const trialAte = summary.trial_ends_at
    ? new Date(summary.trial_ends_at).toLocaleDateString('pt-BR')
    : null

  return (
    <div className="apc-card">
      <div className="apc-header">
        <CreditCard size={18} strokeWidth={1.75} />
        <h3>Plano da conta</h3>
      </div>

      <div className="apc-current">
        <span className="apc-plan-name">{summary.plan_name}</span>
        {currentPlan && (
          <span className="apc-current-price">
            {fmtPrice(currentPlan.price_cents, currentPlan.currency, currentPlan.interval)}
          </span>
        )}
        {emTeste && trialAte && (
          <span className="apc-badge apc-badge--trial">Teste até {trialAte}</span>
        )}
        {rebaixado && (
          <span className="apc-badge apc-badge--warn">Assinatura vencida — no freemium</span>
        )}
      </div>

      <div className="apc-usages">
        <UsageBar label="Usuários" used={summary.users_count} max={summary.limits?.max_users} />
        <UsageBar label="Clientes" used={summary.clients_count} max={summary.limits?.max_clients} />
        <UsageBar label="Módulos" used={summary.modules_count} max={summary.limits?.max_modules} />
      </div>

      <div className="apc-request">
        <span className="apc-request-title">Solicitar mudança de plano</span>
        {myPending ? (
          <p className="apc-pending">
            Você já tem uma solicitação pendente para o plano{' '}
            <strong>{myPending.requested_plan_name}</strong>. Nossa equipe vai avaliar.
          </p>
        ) : (
          <>
            <div className="apc-request-row">
              <select
                className="apc-select"
                value={requestPlanId}
                onChange={e => setRequestPlanId(e.target.value)}
              >
                <option value="">Escolha um plano…</option>
                {(plans ?? [])
                  .filter(p => p.active && p.slug !== summary.plan_slug)
                  .map(p => (
                    <option key={p.id} value={p.id}>
                      {p.name}
                    </option>
                  ))}
              </select>
              <Button
                onClick={() => mutation.mutate()}
                loading={mutation.isPending}
                disabled={!requestPlanId}
              >
                <Send size={15} strokeWidth={1.75} />
                Solicitar
              </Button>
            </div>

            {selectedPlan && (
              <div className={`apc-compare apc-compare--${changeKind}`}>
                <div className="apc-compare-head">
                  {changeKind === 'upgrade' && (
                    <>
                      <ArrowUpCircle size={16} strokeWidth={2} />
                      <span>Upgrade de plano</span>
                    </>
                  )}
                  {changeKind === 'downgrade' && (
                    <>
                      <ArrowDownCircle size={16} strokeWidth={2} />
                      <span>Downgrade de plano</span>
                    </>
                  )}
                  {changeKind === 'lateral' && (
                    <>
                      <ArrowRightCircle size={16} strokeWidth={2} />
                      <span>Mudança lateral (mesmo valor)</span>
                    </>
                  )}
                  <span className="apc-compare-price">
                    {fmtPrice(
                      selectedPlan.price_cents,
                      selectedPlan.currency,
                      selectedPlan.interval
                    )}
                  </span>
                </div>

                <div className="apc-compare-limits">
                  <div className="apc-compare-limit">
                    <span>Usuários</span>
                    <span>
                      {fmtLimit(currentPlan?.limits?.max_users)} →{' '}
                      <strong>{fmtLimit(selectedPlan.limits?.max_users)}</strong>
                    </span>
                  </div>
                  <div className="apc-compare-limit">
                    <span>Clientes</span>
                    <span>
                      {fmtLimit(currentPlan?.limits?.max_clients)} →{' '}
                      <strong>{fmtLimit(selectedPlan.limits?.max_clients)}</strong>
                    </span>
                  </div>
                  <div className="apc-compare-limit">
                    <span>Módulos</span>
                    <span>
                      {fmtLimit(currentPlan?.limits?.max_modules)} →{' '}
                      <strong>{fmtLimit(selectedPlan.limits?.max_modules)}</strong>
                    </span>
                  </div>
                </div>

                {changeKind === 'downgrade' && (
                  <p className="apc-compare-warn">
                    Atenção: limites menores. Se seu uso atual ultrapassar os novos limites, você
                    não conseguirá criar novos registros até ajustar.
                  </p>
                )}
              </div>
            )}

            <textarea
              className="apc-message"
              value={message}
              onChange={e => setMessage(e.target.value)}
              placeholder="Mensagem (opcional): conte o que você precisa."
              rows={2}
            />
          </>
        )}
      </div>
    </div>
  )
}
