import { type FormEvent, useState } from 'react'
import { Check, Copy } from 'lucide-react'
import Modal from '@/components/ui/Modal'
import Input from '@/components/ui/Input'
import Button from '@/components/ui/Button'
import { useCreateUser, useUpdateUser } from '@/hooks/useUsers'
import { toast } from '@/lib/toast'
import type { User } from '@/types/database'

interface TherapistFormModalProps {
  isOpen: boolean
  onClose: () => void
  user: User | null
}

export default function TherapistFormModal({ isOpen, onClose, user }: TherapistFormModalProps) {
  const createMutation = useCreateUser()
  const updateMutation = useUpdateUser()

  const [name, setName] = useState(user?.name ?? '')
  const [email, setEmail] = useState(user?.email ?? '')
  const [role, setRole] = useState<'owner' | 'therapist'>(user?.role ?? 'therapist')

  // Depois de criar, mostramos a senha temporária para o owner copiar e repassar.
  const [tempPassword, setTempPassword] = useState<string | null>(null)
  const [createdEmail, setCreatedEmail] = useState('')
  const [copied, setCopied] = useState(false)

  const isEditing = !!user

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault()

    if (!name.trim()) {
      toast('Nome é obrigatório', 'error')
      return
    }

    if (!isEditing && !email.trim()) {
      toast('Email é obrigatório', 'error')
      return
    }

    try {
      if (isEditing) {
        await updateMutation.mutateAsync({
          userId: user.id,
          data: { name, role },
        })
        toast('Terapeuta atualizado com sucesso')
        onClose()
      } else {
        const result = await createMutation.mutateAsync({ name, email, role })
        setCreatedEmail(email)
        setTempPassword(result.tempPassword)
        toast('Terapeuta criado com sucesso')
        // NÃO fecha: mostra a senha temporária para o owner copiar.
      }
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Erro ao salvar'
      toast(message, 'error')
    }
  }

  const handleCopy = async () => {
    if (!tempPassword) return
    try {
      await navigator.clipboard.writeText(tempPassword)
      setCopied(true)
      toast('Senha copiada!')
      setTimeout(() => setCopied(false), 2000)
    } catch {
      toast('Não foi possível copiar automaticamente', 'error')
    }
  }

  const isLoading = createMutation.isPending || updateMutation.isPending

  if (!isOpen) return null

  // --- Tela pós-criação: senha temporária ---
  if (tempPassword) {
    return (
      <Modal
        title="Terapeuta criado"
        onClose={onClose}
        onSubmit={e => {
          e.preventDefault()
          onClose()
        }}
        submitLabel="Concluir"
      >
        <div className="form-stack">
          <p className="settings-description">
            Envie estas credenciais para <strong>{createdEmail}</strong>. No primeiro acesso, o
            terapeuta será obrigado a definir uma nova senha.
          </p>

          <div className="temp-password-box">
            <div>
              <label className="form-label">Senha temporária</label>
              <code className="temp-password-value">{tempPassword}</code>
            </div>
            <Button type="button" variant="secondary" size="sm" onClick={handleCopy}>
              {copied ? <Check size={16} /> : <Copy size={16} />}
              {copied ? 'Copiado' : 'Copiar'}
            </Button>
          </div>

          <p className="settings-description">
            Esta senha não será exibida novamente. Se perder, exclua e recrie o terapeuta.
          </p>
        </div>
      </Modal>
    )
  }

  // --- Formulário de criação/edição ---
  return (
    <Modal
      title={isEditing ? 'Editar Terapeuta' : 'Novo Terapeuta'}
      onClose={onClose}
      onSubmit={handleSubmit}
      submitLabel={isEditing ? 'Salvar' : 'Criar'}
      submitDisabled={isLoading || !name.trim()}
    >
      <div className="form-stack">
        <Input
          label="Nome"
          value={name}
          onChange={e => setName(e.target.value)}
          placeholder="Nome completo"
          required
          autoFocus
        />

        <div className="form-group">
          <label className="form-label">Papel</label>
          <div className="role-selector">
            <button
              type="button"
              className={`role-option ${role === 'therapist' ? 'role-option--active' : ''}`}
              onClick={() => setRole('therapist')}
            >
              <strong>Terapeuta</strong>
              <span>Vê e edita só os próprios atendimentos</span>
            </button>
            <button
              type="button"
              className={`role-option ${role === 'owner' ? 'role-option--active' : ''}`}
              onClick={() => setRole('owner')}
            >
              <strong>Owner</strong>
              <span>Gerencia a conta e vê todos os atendimentos</span>
            </button>
          </div>
        </div>

        {!isEditing && (
          <>
            <Input
              label="Email"
              type="email"
              value={email}
              onChange={e => setEmail(e.target.value)}
              placeholder="email@exemplo.com"
              required
            />
            <p className="settings-description">
              Uma senha temporária será gerada. O terapeuta define a própria senha no primeiro
              acesso.
            </p>
          </>
        )}
      </div>
    </Modal>
  )
}
