import { useState } from 'react'
import { Edit2, Plus, Trash2, User as UserIcon, Users } from 'lucide-react'
import Button from '@/components/ui/Button'
import { Skeleton } from '@/components/ui/Skeleton'
import EmptyState from '@/components/ui/EmptyState'
import { useDeleteUser, useUsers } from '@/hooks/useUsers'
import { toast } from '@/lib/toast'
import { confirm } from '@/lib/confirm'
import TherapistFormModal from './TherapistFormModal'
import type { User } from '@/types/database'
import './Admin.css'

/**
 * Gestão de terapeutas como SEÇÃO da aba "Conta" em Configurações.
 * É owner-only por herdar o gate {activeTab === 'clinic' && isOwner} do SettingsPage.
 */
export default function TherapistsSection() {
  const { data: users, isLoading } = useUsers()
  const deleteMutation = useDeleteUser()

  const [modalOpen, setModalOpen] = useState(false)
  const [editingUser, setEditingUser] = useState<User | null>(null)

  const handleCreate = () => {
    setEditingUser(null)
    setModalOpen(true)
  }

  const handleEdit = (user: User) => {
    setEditingUser(user)
    setModalOpen(true)
  }

  const handleDelete = async (user: User) => {
    const confirmed = await confirm({
      message: `Tem certeza que deseja excluir "${user.name}"?`,
      details: 'Esta ação não pode ser desfeita.',
      confirmLabel: 'Excluir',
      variant: 'danger',
    })

    if (confirmed) {
      try {
        await deleteMutation.mutateAsync(user.id)
        toast('Terapeuta excluído com sucesso')
      } catch {
        toast('Erro ao excluir terapeuta', 'error')
      }
    }
  }

  const handleModalClose = () => {
    setModalOpen(false)
    setEditingUser(null)
  }

  return (
    <div className="settings-card">
      <div className="settings-card-header">
        <div>
          <h3>Terapeutas</h3>
          <p className="settings-description">
            Gerencie os terapeutas que podem acessar esta conta.
          </p>
        </div>
        <Button size="sm" onClick={handleCreate}>
          <Plus size={16} />
          Novo Terapeuta
        </Button>
      </div>

      {isLoading ? (
        <div className="admin-list">
          {[1, 2, 3].map(i => (
            <Skeleton key={i} height="64px" />
          ))}
        </div>
      ) : !users?.length ? (
        <EmptyState
          icon={<Users size={40} />}
          title="Nenhum terapeuta cadastrado"
          description="Adicione terapeutas para que possam acessar o sistema"
          action={
            <Button onClick={handleCreate}>
              <Plus size={18} />
              Adicionar Terapeuta
            </Button>
          }
        />
      ) : (
        <div className="admin-list">
          <div className="admin-list-header">
            <span>Nome</span>
            <span>Email</span>
            <span>Ações</span>
          </div>

          {users.map(user => (
            <div key={user.id} className="admin-list-row">
              <div className="admin-user-info">
                <div className="admin-user-avatar">
                  {user.avatar_url ? <img src={user.avatar_url} alt="" /> : <UserIcon size={20} />}
                </div>
                <span className="admin-user-name">{user.name}</span>
              </div>

              <span className="admin-user-email">{user.email}</span>

              <div className="admin-actions">
                <Button variant="ghost" size="sm" onClick={() => handleEdit(user)} title="Editar">
                  <Edit2 size={16} />
                </Button>
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={() => handleDelete(user)}
                  title="Excluir"
                >
                  <Trash2 size={16} />
                </Button>
              </div>
            </div>
          ))}
        </div>
      )}

      {modalOpen && (
        <TherapistFormModal
          key={editingUser?.id ?? 'new'}
          isOpen={modalOpen}
          onClose={handleModalClose}
          user={editingUser}
        />
      )}
    </div>
  )
}
